        stream = torch.cuda.current_stream(x.device)
        mod = _get_ptx_module()
        mod.launch(
            "ln_partial_f32",
            grid=(rows, nsplit, 1),
            block=(256, 1, 1),
            arguments=[x, partials, i32(n), i32(chunk)],
            shared_memory=0,
            stream=stream,
        )
        mod.launch(
            "layernorm_f32",
            grid=(rows, nsplit, 1),
            block=(256, 1, 1),
            arguments=[x, out, self.ln.weight, self.ln.bias, partials, i32(n), i32(chunk), i32(nsplit), f32(self.ln.eps)],
            shared_memory=0,
            stream=stream,
        )
        return out

